/* Generated by scripts/build-site.mjs. Offline cache for visited BGW pages. */
const CACHE = 'bgw-runtime-v1';
const ROOT_FILES = ['/', '/index.html', '/manifest.webmanifest'];
const PREFIXES = ["/assets/","/img/","/games/","/gah/","/marrakesh/","/medico/","/burgundy/","/clocktower/","/rebirth/","/energy-empire/","/teotihuacan/","/civolution/","/gaia-project/","/nijar/"];
const ours = url => url.origin === self.location.origin && (ROOT_FILES.includes(url.pathname) || PREFIXES.some(prefix => url.pathname.startsWith(prefix)));
// ?v=<content hash> URLs never change, so the cached copy is always right.
const immutable = url => /^[0-9a-f]{10}$/.test(url.searchParams.get('v') || '');

self.addEventListener('install', () => self.skipWaiting());
self.addEventListener('activate', event => event.waitUntil((async () => {
  for (const key of await caches.keys()) if (key !== CACHE) await caches.delete(key);
  await self.clients.claim();
})()));

async function put(request, response) {
  if (response.ok && response.type === 'basic') (await caches.open(CACHE)).put(request, response.clone());
  return response;
}
async function cacheFirst(request) {
  return (await caches.match(request)) || put(request, await fetch(request));
}
async function staleWhileRevalidate(event) {
  const cached = await caches.match(event.request);
  const refresh = fetch(event.request).then(response => put(event.request, response));
  if (cached) { event.waitUntil(refresh.catch(() => {})); return cached; }
  return refresh;
}
// Pages and unversioned data: fresh when online; a slow table-side connection falls back to cache after 4s.
async function networkFirst(event) {
  const { request } = event;
  const network = fetch(request).then(response => put(request, response));
  event.waitUntil(network.catch(() => {}));
  const timeout = new Promise(resolve => setTimeout(resolve, 4000));
  try {
    const response = await Promise.race([network, timeout.then(() => null)]);
    if (response) return response;
  } catch {}
  const cached = await caches.match(request, { ignoreSearch: request.mode === 'navigate' });
  return cached || network;
}

self.addEventListener('fetch', event => {
  const { request } = event;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (!ours(url)) return;
  if (immutable(url)) event.respondWith(cacheFirst(request));
  else if (request.destination === 'image') event.respondWith(staleWhileRevalidate(event));
  else event.respondWith(networkFirst(event));
});
